function SettingsForm({prefs,calendars,connected,busy,demo,onChange,onExport,onDisconnect}:{prefs:Preferences;calendars:Calendar[];connected:boolean;busy:boolean;demo:boolean;onChange:(prefs:Partial<Preferences>)=>void;onExport:()=>void;onDisconnect:()=>void}){
  const [draft,setDraft]=useState(prefs);
  return <form onSubmit={e=>{e.preventDefault();onChange(draft);}}><h3>Appearance</h3><div className="theme-options">{([{id:'light',title:'Light',icon:Sun},{id:'dark',title:'Dark',icon:Moon},{id:'system',title:'System',icon:Monitor}] as const).map(theme=><button key={theme.id} type="button" className={draft.theme===theme.id?'selected':''} onClick={()=>setDraft(d=>({...d,theme:theme.id}))}><theme.icon size={20}/>{theme.title}</button>)}</div><h3>Reminders</h3><label className="toggle-field"><Input type="checkbox" checked={draft.inAppReminders} onChange={e=>setDraft(d=>({...d,inAppReminders:e.target.checked}))}/>Show reminders while Keep Walking is open</label><div className="notice compact-notice">In this version, in-app reminders need the app to be open and visible. For alerts while it is closed, use Google Calendar reminders on events and shared tasks.</div><Field label="Default task reminder"><select value={draft.reminderMinutes} onChange={e=>setDraft(d=>({...d,reminderMinutes:+e.target.value}))}><ReminderOptions/></select></Field><label className="toggle-field"><Input type="checkbox" checked={draft.eveningEnabled} onChange={e=>setDraft(d=>({...d,eveningEnabled:e.target.checked}))}/>Evening nudge when there are no entries today</label><Field label="Evening time"><Input type="time" value={draft.eveningTime} required onChange={e=>setDraft(d=>({...d,eveningTime:e.target.value}))}/></Field>{calendars.length>0&&<Field label="Default calendar for shared tasks"><select value={draft.defaultCalendarId} onChange={e=>setDraft(d=>({...d,defaultCalendarId:e.target.value}))}><option value="">Primary calendar</option>{calendars.map(c=><option key={c.id} value={c.id}>{c.summary}</option>)}</select></Field>}<h3>Your data</h3><button type="button" className="wide-action" onClick={onExport}><Download size={18}/><span><strong>Export a backup</strong><small>Download tasks, plans and progress as JSON.</small></span><ArrowDownIcon/></button>{connected&&<button type="button" className="wide-action" onClick={onDisconnect}><Link2 size={18}/><span>Disconnect Google Calendar on this device</span><X size={15}/></button>}<p className="field-hint">{demo?'Preview data stays in this browser.':'Your records sync through your private Firebase database. Calendar access is remembered on this device while valid. Google sign-in stays active when Calendar asks you to reconnect.'}</p><div className="install-tip"><strong>Keep Walking, one tap away</strong><p>iPhone: open in Safari → Share → Add to Home Screen.<br/>Mac: Safari → File → Add to Dock.</p></div><FormFooter busy={busy} label="Save settings"/></form>;
}
function ArrowDownIcon(){return <Download size={15}/>;}

